mapper.select:
select
  EXAM_NO, EXAM_PARA, DESCRIPTION, IMPRESSION, RECOMMENDATION, IS_ABNORMAL, DEVICE, USE_IMAGE, MEMO, REPORTNAME
from exam_report

    
        and EXAM_NO = #{examNo}
    
    
        and EXAM_PARA = #{examPara}
    
    
        and DESCRIPTION = #{description}
    
    
        and IMPRESSION = #{impression}
    
    
        and RECOMMENDATION = #{recommendation}
    
    
        and IS_ABNORMAL = #{isAbnormal}
    
    
        and DEVICE = #{device}
    
    
        and USE_IMAGE = #{useImage}
    
    
        and MEMO = #{memo}
    
    
        and REPORTNAME = #{reportname}
    

limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from exam_report

    
        and EXAM_NO = #{examNo}
    
    
        and EXAM_PARA = #{examPara}
    
    
        and DESCRIPTION = #{description}
    
    
        and IMPRESSION = #{impression}
    
    
        and RECOMMENDATION = #{recommendation}
    
    
        and IS_ABNORMAL = #{isAbnormal}
    
    
        and DEVICE = #{device}
    
    
        and USE_IMAGE = #{useImage}
    
    
        and MEMO = #{memo}
    
    
        and REPORTNAME = #{reportname}

select er.EXAM_NO, er.EXAM_PARA, er.DESCRIPTION, er.IMPRESSION, er.IS_ABNORMAL, em.exam_class, em.exam_sub_class, em.exam_date_time from exam_report er inner join exam_master em on er.EXAM_NO = em.exam_no
and date_format(em.exam_date_time,'%Y-%m-%d') =#{examReport.params.recordingDate}
order by em.exam_date_time asc limit #{pageable.offset}, #{pageable.pageSize}
